<?php global $currency_symbol;?>	<form id="tour-booking-form" method="post" action="" class="booking" style="display:none">		<fieldset>			<h3><span>01 </span><?php _e('Submit tour booking', 'bookyourtravel') ?></h3>			<div class="error" style="display:none;"><span><p></p></span></div>			<div class="row twins">				<div class="f-item">					<label for="first_name"><?php _e('First name', 'bookyourtravel') ?></label>					<input type="text" id="first_name" name="first_name" data-required />				</div>				<div class="f-item">					<label for="last_name"><?php _e('Last name', 'bookyourtravel') ?></label>					<input type="text" id="last_name" name="last_name" data-required />				</div>			</div>						<div class="row twins">				<div class="f-item">					<label for="email"><?php _e('Email address', 'bookyourtravel') ?></label>					<input type="email" id="email" name="email" data-required />				</div>				<div class="f-item">					<label for="confirm_email"><?php _e('Confirm email address', 'bookyourtravel') ?></label>					<input type="email" id="confirm_email" name="confirm_email" data-required data-conditional="confirm" />				</div>				<span class="info"><?php _e('You\'ll receive a confirmation email', 'bookyourtravel') ?></span>			</div>						<div class="row">				<div class="f-item">					<label for="phone"><?php _e('Phone', 'bookyourtravel') ?></label>					<input type="text" id="phone" name="phone" data-required />				</div>			</div>					<div class="row twins">				<div class="f-item">					<label for="address"><?php _e('Street Address and Number', 'bookyourtravel') ?></label>					<input type="text" id="address" name="address" data-required />				</div>				<div class="f-item">					<label for="town"><?php _e('Town / City', 'bookyourtravel') ?></label>					<input type="text" id="town" name="town" data-required />				</div>			</div>			<div class="row twins">				<div class="f-item">					<label for="zip"><?php _e('ZIP Code', 'bookyourtravel') ?></label>					<input type="text" id="zip" name="zip" data-required />				</div>				<div class="f-item">					<label for="country"><?php _e('Country', 'bookyourtravel') ?></label>					<input type="text" id="country" name="country" data-required />				</div>			</div>						<div class="row twins">				<div class="f-item">					<label for="tour_name"><?php _e('Tour name', 'bookyourtravel') ?></label>					<span id="tour_name" name="tour_name"></span>				</div>				<div class="f-item">					<label for="start_date"><?php _e('Start date', 'bookyourtravel') ?></label>					<span id="start_date" name="start_date"></span>				</div>			</div>						<div class="row">				<div class="f-item">					<label for="room_price"><?php _e('Price', 'bookyourtravel') ?></label>					<div class="price">						<span class="curr"><?php echo $currency_symbol; ?></span>						<span id="total_price" name="total_price" class="amount"></span>					</div>				</div>			</div>			<div class="row">				<div class="f-item">					<label><?php _e('Special requirements: <span>(Not Guaranteed)</span>', 'bookyourtravel') ?></label>					<textarea id="requirements" name="requirements" rows="10" cols="10"></textarea>				</div>				<span class="info"><?php _e('Please write your requests in English.', 'bookyourtravel') ?></span>			</div>			<input type="hidden" name="tour_schedule_id" id="tour_schedule_id" />			<input type="submit" class="gradient-button" value="<?php _e('Submit tour booking', 'bookyourtravel') ?>" id="submit-tour-booking" name="submit-tour-booking" />			<a href="javascript:void(0);" class="gradient-button cancel-tour-booking" title="<?php _e('Cancel', 'bookyourtravel') ?>" id="cancel-tour-booking"><?php _e('Cancel', 'bookyourtravel') ?></a>		</fieldset>	</form><?php ?>